code.source:
#include <iostream>
using namespace std;

struct Vec {
    int x, y;
    Vec operator+(const Vec& other) const {
        return {x + other.x, y + other.y};
    }
};

int main() {
    Vec a{1, 2};
    Vec b{10, 20};
    Vec c = a + b;
    cout << c.x << " " << c.y << endl;
    return 0;
}

#include <iostream>
using namespace std;

struct Vec {
    int x, y;
};

ostream& operator<<(ostream& out, const Vec& v) {
    return out << "(" << v.x << ", " << v.y << ")";
}

int main() {
    Vec a{3, 4};
    cout << "Point " << a << endl;
    return 0;
}

